def is_power_of_three(n):
    if n <= 0:
        return False
    while n > 1:
        n //= 3
    return n == 1

solutions = []
# Since 2^a < 35, a can be 1, 2, 3, 4, 5
for a in range(1, 6):
    two_power_a = 2**a
    remainder = 35 - two_power_a

    if remainder <= 0:
        continue

    if is_power_of_three(remainder):
        # Find b such that 3^b = remainder
        b = 0
        temp = remainder
        while temp > 1:
            temp //= 3
            b += 1
        solutions.append((a, b))

print(f"Solutions found: {solutions}")
